/* Google Calendar ships a fixed-size iframe. Wrap it so it scales with the
       column instead of overflowing on a phone. */
    .gcal-frame {
      position: relative;
      width: 100%;
      height: 680px;
      border-radius: var(--radius-md);
      overflow: hidden;
      border: 1px solid var(--gray-100);
      box-shadow: var(--shadow-sm);
      background: var(--white);
    }
    .gcal-frame iframe { width: 100%; height: 100%; border: 0; display: block; }
    @media (max-width: 768px) { .gcal-frame { height: 520px; } }

    .recurring-list { display: flex; flex-direction: column; gap: .9rem; }
    .recurring-item { display: flex; gap: .75rem; align-items: flex-start; font-size: .92rem; }
    .recurring-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green-700); margin-top: 7px; flex-shrink: 0; }
    .recurring-item span { color: var(--gray-600); }
    .recurring-item strong { color: var(--gray-800); }

