/* align-items:start so the Friday card sizes to its own content. Stretching
       it to match the tall Iqamah table left a large hollow panel on the weeks
       when no khateeb is scheduled yet. */
    .prayers-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; align-items: start; }
    .friday-card { background: var(--green-800); color: var(--white); border-radius: var(--radius-md); padding: 2rem; }
    .friday-times { display: flex; gap: 2.5rem; margin: 1.25rem 0 1.5rem; padding: 1.1rem 0; border-top: 1px solid rgba(255,255,255,.18); border-bottom: 1px solid rgba(255,255,255,.18); }
    .friday-time__name { display: block; font-size: .7rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: rgba(255,255,255,.62); margin-bottom: .3rem; }
    .friday-time__value { display: block; font-family: var(--font-serif); font-size: 1.55rem; font-weight: 700; color: var(--gold-400); line-height: 1; }
    .friday-card__khateeb { margin-top: .25rem; }
    .friday-card h3 { color: var(--gold-400); font-family: var(--font-serif); font-size: 1.4rem; margin-bottom: 1rem; }
    .friday-card p { color: rgba(255,255,255,.8); margin-bottom: .5rem; font-size: .95rem; }
    .friday-card strong { color: var(--white); }
    .adhan-note { background: var(--gold-100); border: 1px solid #f0d9a8; border-radius: var(--radius-sm); padding: 1rem 1.25rem; font-size: .9rem; color: var(--gray-700); }
