(function () {
      var tabs = document.querySelectorAll(".tab-btn");
      var panels = document.querySelectorAll(".tab-panel");
      function showTab(name) {
        tabs.forEach(function (t) {
          var active = t.dataset.tab === name;
          t.classList.toggle("active", active);
          t.setAttribute("aria-selected", active);
        });
        panels.forEach(function (p) {
          p.classList.toggle("active", p.dataset.panel === name);
        });
      }
      function selectTab(name, focus) {
        showTab(name);
        history.replaceState(null, "", "#" + name);
        if (focus) {
          var btn = document.querySelector('.tab-btn[data-tab="' + name + '"]');
          if (btn) btn.focus();
        }
      }

      tabs.forEach(function (t, i) {
        t.addEventListener("click", function () {
          selectTab(t.dataset.tab, false);
        });
        // Left/Right arrows move between tabs, which is what screen reader
        // and keyboard users expect from anything marked up as a tablist.
        t.addEventListener("keydown", function (e) {
          var dir = e.key === "ArrowRight" ? 1 : e.key === "ArrowLeft" ? -1 : 0;
          if (!dir) return;
          e.preventDefault();
          var next = (i + dir + tabs.length) % tabs.length;
          selectTab(tabs[next].dataset.tab, true);
        });
      });

      var initial = location.hash.replace("#", "");
      if (initial === "welcome" || initial === "events") showTab(initial);
    })();
